// P in registers as A fragment (computed from mma on P itself loaded via ldmatrix)
__global__ void gemm_pv(const __nv_bfloat16* p, const __nv_bfloat16* v,
                        int variant, float* out) {
  __shared__ __align__(16) __nv_bfloat16 sP[16][16];
  __shared__ __align__(16) __nv_bfloat16 sV[16][16];
  int tid = threadIdx.x;
  for (int i = tid; i < 256; i += 32) {
    sP[i / 16][i % 16] = p[i];
    sV[i / 16][i % 16] = v[i];
  }
  __syncthreads();
  int lane = tid % 32;
  uint32_t a[4], b[2];
  ldmatrix_x4(a, quad_addr(sP, lane, 16));
  uint32_t vf[4];
  if (variant == 0) ldmatrix_x4(vf, quad_addr(sV, lane, 16));
  else ldmatrix_x4_t(vf, quad_addr(sV, lane, 16));
  float c[4] = {0, 0, 0, 0}, d[4];
  b[0] = vf[0]; b[1] = vf[2];
  mma_m16n8k16(d, a, b, c);
  for (int j = 0; j < 4; j++) out[lane * 8 + j] = d[j];
  b[0] = vf[1]; b[1] = vf[3];
  mma_m16n8k16(d, a, b, c);
  for (int j = 0; j < 4; j++) out[lane * 8 + 4 + j] = d[j];
