static void check_qkt(int variant, float* d_out) {
  // reference Q*K^T with Q[i][j]=i*16+j+1, K[i][j]=i*16+j+101
  float h[32 * 8];
  cudaMemcpy(h, d_out, sizeof(h), cudaMemcpyDeviceToHost);
  float err = 0;
  for (int l = 0; l < 32; l++) for (int j = 0; j < 8; j++) {
    float got = h[l * 8 + j];
    int row = (j < 4) ? l / 4 : l / 4 + 8;
    int col = 2 * (l % 4) + (j % 2) + 8 * (j / 4);
    float ref = 0;
    for (int d = 0; d < 16; d++) ref += (float)((row) * 16 + d + 1) * (float)((col) * 16 + d + 101);
    float e = got - ref; if (e < 0) e = -e;
    if (e > err) err = e;
  }
  printf("QK^T variant %d: max err %.4f\n", variant, err);
}

static void check_pv(int variant, float* d_out) {
  // reference P*V with P[i][j]=i*16+j+1, V[i][j]=i*16+j+101
  float h[32 * 8];
